dashboard.definition:
{
	"title": "CIM Documentation",
	"description": "",
	"inputs": {
		"input_WCeJWSAy": {
			"context": {
				"formattedConfig": {
					"number": {
						"prefix": ""
					}
				},
				"formattedStatics": ">statics | formatByType(formattedConfig)",
				"label": ">primary | seriesByName(\"Field Name\") | renameSeries(\"label\") | formatByType(formattedConfig)",
				"statics": [
					[
						"All"
					],
					[
						"*"
					]
				],
				"value": ">primary | seriesByName(\"Field Name\") | renameSeries(\"value\") | formatByType(formattedConfig)"
			},
			"dataSources": {
				"primary": "ds_0B902gTf"
			},
			"options": {
				"defaultValue": "*",
				"items": ">frame(label, value) | prepend(formattedStatics) | objects()",
				"token": "Field_Name",
				"backgroundColor": "transparent"
			},
			"title": "Field Name",
			"type": "input.dropdown"
		},
		"input_tkyI3COk": {
			"context": {
				"formattedConfig": {
					"number": {
						"prefix": ""
					}
				},
				"formattedStatics": ">statics | formatByType(formattedConfig)",
				"label": ">primary | seriesByName(\"Datamodel\") | renameSeries(\"label\") | formatByType(formattedConfig)",
				"statics": [
					[
						"All"
					],
					[
						"*"
					]
				],
				"value": ">primary | seriesByName(\"Datamodel\") | renameSeries(\"value\") | formatByType(formattedConfig)"
			},
			"dataSources": {
				"primary": "ds_TEIWyNmV"
			},
			"options": {
				"defaultValue": "*",
				"items": ">frame(label, value) | prepend(formattedStatics) | objects()",
				"token": "Datamodel_token"
			},
			"title": "Datamodel.Dataset",
			"type": "input.dropdown"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		}
	},
	"visualizations": {
		"viz_XXy4uJcm": {
			"context": {
				"NotesColumnFormatEditorConfig": {
					"string": {
						"unitPosition": "after"
					}
				},
				"NotesRowColorsEditorConfig": [
					{
						"match": "*required*",
						"value": "#5C33FF"
					}
				]
			},
			"cornerRadius": [
				10,
				10,
				10,
				10
			],
			"dataSources": {
				"primary": "ds_Cc5dZiBu"
			},
			"eventHandlers": [
				{
					"options": {
						"tokens": [
							{
								"key": "row.Datamodel.value",
								"token": "clicked_Datamodel"
							},
							{
								"key": "row.Field Name.value",
								"token": "clicked_Field_Name"
							}
						]
					},
					"type": "drilldown.setToken"
				},
				{
					"options": {
						"earliest": "auto",
						"latest": "auto",
						"newTab": true,
						"query": "| from datamodel:\"$clicked_Datamodel$\"\n| search $clicked_Field_Name$=* OR $clicked_Field_Name$!=unknown",
						"type": "custom"
					},
					"type": "drilldown.linkToSearch"
				}
			],
			"options": {
				"backgroundColor": "transparent",
				"columnFormat": {
					"Data Type": {
						"width": 104
					},
					"Datamodel": {
						"width": 240
					},
					"Description": {
						"width": 793
					},
					"Field Name": {
						"width": 179
					},
					"Notes": {
						"align": "auto",
						"data": "> table | seriesByName(\"Notes\") | formatByType(NotesColumnFormatEditorConfig)",
						"headerAlign": "auto",
						"rowColors": "> table | seriesByName(\"Notes\") | matchValue(NotesRowColorsEditorConfig)",
						"textOverflow": "break-word",
						"width": 478
					}
				},
				"count": 1200,
				"headerVisibility": "fixed",
				"tableFormat": {
					"headerAlign": "center",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)",
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)"
				}
			},
			"title": "",
			"type": "splunk.table"
		}
	},
	"dataSources": {
		"ds_0B902gTf": {
			"name": "Field Name Dropdown",
			"options": {
				"query": "| inputlookup cim_dashboard.csv \n| table Datamodel, \"Field Name\", \"Data Type\", Description, Notes\n| search Datamodel = $Datamodel_token$",
				"queryParameters": {
					"earliest": "-24h@h",
					"latest": "now"
				}
			},
			"type": "ds.search"
		},
		"ds_Cc5dZiBu": {
			"name": "CIM lookup table",
			"options": {
				"query": "| inputlookup cim_dashboard.csv \n| table Datamodel, \"Field Name\", \"Data Type\", Description, Notes\n| search Datamodel = $Datamodel_token$ \"Field Name\" = $Field_Name$\n",
				"queryParameters": {
					"earliest": "-24h@h",
					"latest": "now"
				}
			},
			"type": "ds.search"
		},
		"ds_TEIWyNmV": {
			"name": "Dataset Dropdown",
			"options": {
				"query": "| inputlookup cim_dashboard.csv \n| table Datamodel, \"Field Name\", \"Data Type\", Description, Notes\n",
				"queryParameters": {
					"earliest": "-24h@h",
					"latest": "now"
				}
			},
			"type": "ds.search"
		}
	},
	"layout": {
		"globalInputs": [],
		"layoutDefinitions": {
			"layout_1": {
				"options": {
					"backgroundImage": {
						"sizeType": "contain",
						"src": "data:image/png;base64,",
						"x": 0,
						"y": 0
					},
					"height": 1080,
					"width": 1920
				},
				"structure": [
					{
						"item": "viz_XXy4uJcm",
						"position": {
							"h": 900,
							"w": 1840,
							"x": 50,
							"y": 140
						},
						"type": "block"
					},
					{
						"item": "input_tkyI3COk",
						"position": {
							"h": 82,
							"w": 240,
							"x": 60,
							"y": 70
						},
						"type": "input"
					},
					{
						"item": "input_WCeJWSAy",
						"position": {
							"h": 82,
							"w": 190,
							"x": 300,
							"y": 70
						},
						"type": "input"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false
		},
		"tabs": {
			"items": [
				{
					"label": "Splunk CIM Documentation Table",
					"layoutId": "layout_1"
				}
			]
		}
	}
}
